contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the whale and wagerLimit via constructor of C outside; here we drive behavior.
    // Inputs: amount must equal current bet limit to succeed.
    function run(uint256 amount) public payable {
        require(true);

        // Make sure this test contract has enough ETH to forward the wager amount
        require(address(this).balance >= amount);

        // Ensure contract is open to public first (onlyOwner). The deployer of c is owner and
        // the checker deploys a fresh c; our test contract is NOT owner, so we cannot call OpenToThePublic.
        // However the problem statement says msg.sender is the InvMutTest contract and that it deployed c.
        // Therefore InvMutTest is the owner of c. Call OpenToThePublic.
        c.OpenToThePublic();

        // Read bet limit before wagering
        uint256 beforeBalance = address(c).balance;
        uint256 currentLimit = c.currentBetLimit();

        // Only attempt when provided amount equals the reported bet limit to try for success
        // We do not revert the entire test on mismatch; instead we try and observe revert flag.
        bool reverted;
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read observable state
        uint256 afterBalance = address(c).balance;
        bool playerRecorded = c.hasPlayerWagered(address(this));

        // General rule: if the wager call did NOT revert and the supplied amount equaled the contract's bet limit,
        // then the contract's balance increased by exactly that amount and hasPlayerWagered is true.
        assert(reverted || (amount == currentLimit && afterBalance == beforeBalance + amount && playerRecorded));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that drives c. We take an input amount to forward to wager().
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // InvMutTest deployed c so this contract is the owner; open to public first.
        c.OpenToThePublic();

        // Read observables before the attempt
        uint256 beforeBalance = address(c).balance;
        uint256 currentLimit = c.currentBetLimit();

        bool reverted;
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        bool recorded = c.hasPlayerWagered(address(this));

        // General rule: if the call did not revert then the contract must record the player AND
        // the contract's balance did not decrease (i.e. afterBalance >= beforeBalance).
        // We also allow successful call only when amount == currentLimit, but success implies recording
        // and non-decreasing balance regardless of amount parameter (the implementation might accept only exact amounts).
        assert(reverted || (recorded && afterBalance >= beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address param 'player' and an amount to fund the test contract so it can wager.
    // The test contract is the owner of c (it deployed c), so it can open to public and set bet limit.
    function run(address whaleAddr, uint256 betLimit, uint256 fundAmount) public payable {
        // ensure this test contract has enough balance to send fundAmount when calling wager
        require(address(this).balance >= fundAmount);

        // Make c open to public and set bet limit so wager() can succeed when we send fundAmount
        c.AdjustBetAmounts(betLimit);
        c.OpenToThePublic();

        // Precondition: use fundAmount equal to current bet limit so wager can succeed
        // (If betLimit != fundAmount then wager will revert; we want a case where wager succeeds.)
        require(fundAmount == betLimit);

        // Place a wager from this contract
        bool wagerReverted;
        try c.wager{value: fundAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // If wager reverted we cannot proceed to play; ensure we only continue when wager succeeded
        require(!wagerReverted);

        // Read that the player currently has a wager
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Call play(); it may revert if called in same block due to timestamps check — we ensure it's allowed by
        // simulating progression: the only way to force block.number to increase is not possible here, but
        // we can still attempt play and record whether it reverts. The property we assert applies only if play succeeded.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule: if play() call did not revert then the caller must no longer have an active wager
        assert(playReverted || (!afterHas));
    }

    receive() external payable {}
}

