contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates an external EOA by calling c from this contract; we must provide the wager amount
    // and first ensure the contract is open and betLimit equals the amount we will send.
    function run(uint256 openingFlag, uint256 amount) public payable {
        // openingFlag used to decide whether we call OpenToThePublic; any nonzero means call it.
        // We must be able to pay `amount` to c when wagering.
        require(address(this).balance >= amount);

        // Make sure this contract is the owner of c (per deployment assumption in the problem statement)
        // If openingFlag!=0, call OpenToThePublic as owner to allow wagers.
        if (openingFlag != 0) {
            c.OpenToThePublic();
        }

        // Adjust the bet limit to the provided amount so that wager() will accept exactly that value.
        c.AdjustBetAmounts(amount);

        // record balance before
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        // try to wager by sending exactly `amount`
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt: if the call did not revert then hasPlayerWagered(this) must be true and balance increased by amount.
        // If it reverted then hasPlayerWagered must be false and balance unchanged.
        bool afterHas = c.hasPlayerWagered(address(this));
        uint256 afterBalance = address(c).balance;

        assert(
            // successful wager implies observable effects
            (!reverted && afterHas && afterBalance == beforeBalance + amount)
            // failed wager implies no wager recorded and no balance change
            || (reverted && !afterHas && afterBalance == beforeBalance)
        );
    }

    // accept refunds or transfers if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model an EOA by this contract calling c. We need to: open the contract, set bet limit,
    // place a wager (sending amount), then invoke play() and observe effects.
    function run(uint256 openFlag, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // If requested, open to public so calls requiring isOpenToPublic pass
        if (openFlag != 0) {
            c.OpenToThePublic();
        }

        // Set the bet limit to `amount` so wager() accepts exactly that value
        c.AdjustBetAmounts(amount);

        // Record contract balance before wagering
        uint256 beforeBalance = address(c).balance;

        // Place wager by sending exactly `amount` (may revert)
        bool wagerReverted;
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // If wager succeeded, hasPlayerWagered must be true; capture current values
        bool afterHas = c.hasPlayerWagered(address(this));
        uint256 midBalance = address(c).balance;

        // Now attempt play(); it may revert. We must call it as its own top-level statement.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read observables after play()
        bool finalHas = c.hasPlayerWagered(address(this));
        uint256 finalBalance = address(c).balance;
        uint256 currentBet = c.currentBetLimit();
        uint256 winnersPot = c.winnersPot();

        // General property:
        // - If the initial wager reverted then nothing should have been recorded and balances unchanged.
        // - If wager succeeded and play reverted, then either the player still has a wager (play reverted before clearing)
        //   or the wager was cleared (if play cleared then it must have done so without transferring more than allowed).
        // - If play succeeded, the player's wager must be cleared and the final balance decreased by at most max(loss, payout):
        //    loss transfers betLimit/2 to whale (observable as at most betLimit/2 decrease),
        //    payout transfers winnersPot (which equals address(c).balance/2 at payout time) but as an upper bound we allow
        //    finalBalance <= midBalance (some ETH may be transferred out). We assert that if play succeeded then hasPlayerWagered is false.

        // Compose the assert to be a general rule over all inputs/paths:
        assert(
            // case: wager failed -> no change
            (wagerReverted && !afterHas && midBalance == beforeBalance && finalBalance == beforeBalance)
            ||
            // case: wager succeeded
            (!wagerReverted && afterHas && midBalance == beforeBalance + amount && (
                // subcase: play reverted -> either wager still present or if cleared then finalBalance not decreased by more than amount (safety)
                (playReverted && (finalHas || (!finalHas && finalBalance + amount >= midBalance)))
                ||
                // subcase: play succeeded -> wager must be cleared and final balance is <= midBalance (funds may have been paid out)
                (!playReverted && !finalHas && finalBalance <= midBalance)
            ))
        );
    }

    // Allow receiving ETH forwarded from C if any
    receive() external payable {}
}

