contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to configure betLimit and difficulty and to fund a wager equal to betLimit.
    // The test will: set bet limit, open to public, place a wager by sending `amount==betLimit`,
    // advance state by relying on block number difference via a dummy call (we cannot change block number here,
    // but play requires timestamps[msg.sender] < block.number; since constructor deployed c and this contract
    // calls wager and then play in the same transaction, play would revert — to make the property general
    // we accept that play might revert; the rule only applies when play does NOT revert after a prior successful wager.
    function run(address whale, uint256 initialBetLimit, uint256 amount, uint256 diff) public payable {
        // ensure we can forward Ether if needed
        if (amount > 0) require(address(this).balance >= amount);

        // As owner (this test contract deployed C), configure contract and open it
        c.AdjustBetAmounts(initialBetLimit);
        c.OpenToThePublic();
        // read betLimit view
        uint256 betLimit = c.currentBetLimit();

        // Precondition: we will attempt to wager with exactly the bet limit amount
        require(amount == betLimit);

        // capture balance before any actions
        uint256 beforeBal = address(c).balance;

        // Attempt to wager: record whether it reverted
        bool wagerReverted;
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // If wager reverted then we cannot rely on play succeeding based on that wager.
        // Attempt to call play and record whether it reverted.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        uint256 afterBal = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule enforced for all inputs: If the wager succeeded and subsequently play did NOT revert,
        // then the player must no longer be recorded as having an active wager (hasPlayerWagered == false),
        // and the contract balance cannot have dropped by more than one betLimit (i.e., at worst the betLimit was moved out).
        // For all other cases (wager reverted or play reverted) we do not constrain behavior here.
        assert(
            ( !wagerReverted && !playReverted && afterHas == false && afterBal >= beforeBal - betLimit ) ||
            ( wagerReverted || playReverted )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

