                && afterBalance == beforeBalance + amount
                // and amount must have matched the observed bet limit (wager requires msg.value == betLimit)
                && amount == beforeBetLimit
                // and caller must not have been marked as having wagered before the call
                && hadWagerBefore == false
            )
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will set up the minimal state so play() can be called: openToPublic must be true,
    // the test contract must place a wager equal to currentBetLimit, then call play().
    // The asserted invariant: after attempting play(), the contract balance is no greater than before
    // (i.e., play cannot increase the contract's ETH balance).
    function run(address whaleAddr, uint256 wagerLimit, uint256 amount) public payable {
        require(true);

        // Precondition: deployer already constructed c with some state; we must make it openToPublic and set bet limit
        // Only owner can call AdjustBetAmounts / AdjustDifficulty / OpenToThePublic; our test contract is NOT owner.
        // So instead, we rely on the fact that the fresh c passed in may have been constructed with given whale and wagerLimit,
        // but we cannot assume openToPublic. To make progress, we attempt to fund c and then ensure we can place a wager only
        // if OpenToThePublic was already true. We therefore treat both possibilities and assert the invariant in all cases.

        // Read observable pre-state
        uint256 beforeBalance = address(c).balance;
        uint256 currentBet = c.currentBetLimit();
        bool hadPlayerWageredBefore = c.hasPlayerWagered(address(this));

        // We try to wager only if currentBet equals the provided amount parameter and contract is openToPublic.
        // Since openToPublic has no getter, we infer ability to call wager by trying and observing revert.
        bool wagerReverted;
        if (address(this).balance < amount) {
            // ensure we have funds to send if needed
            // nothing we can do in this test to receive funds, so if insufficient, skip calling wager
            wagerReverted = true;
        } else {
            // Attempt to call wager with value `amount` (top-level state-changing call)
            try c.wager{value: amount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }
        }

        // Now attempt to call play(), observing whether it reverts.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: play cannot increase contract balance. If play reverted or wager reverted then nothing guaranteed about balance increase from our actions,
        // but nevertheless the rule we assert is that afterBalance <= beforeBalance OR play reverted OR wager reverted.
        // This is a general property: any successful play (which might call payout or loseWager) should not increase contract's balance.
        assert(playReverted || wagerReverted || afterBalance <= beforeBalance);
    }

    // Allow this test contract to receive Ether so it can fund calls when the harness provides it.
    receive() external payable {}
}

