        // and that payout amount cannot exceed half of the contract balance before the call (i.e., afterEth/2 <= beforeEth/2).
        // This captures that payout() transfers at most half of the contract's balance and winnersPot reflects that half.
        assert(reverted || (afterWinnersPot * 2 == afterEth && afterWinnersPot * 2 <= beforeEth));
    }

